// План specs/android-app.md 3.5 / 3.6 (#809888). Pre-Prod, preprod-ttp (TTP Test Locks), EN. Только чтение (@prod-safe).
// 3.5 — веб-эмуляция Pixel 7: Jobs → Pending → открыть работу → «Назад» (history back) → Jobs во вкладке Pending; вкладка в URL (?tab=pending),
// обновление её сохраняет; прямой /jobs без tab — вкладка по умолчанию без ошибок.
// 3.6 — системная «Назад» в APK: нужен Android через CDP, записан как skip.
// Не сверено с сайтом при записи: подписи вкладок (role=tab «Pending …» со счётчиком), ссылка работы — текст JOB-0000.
import { test, expect } from '../../fixtures';
import { ROLE, pp, setEnglish } from './offline-helpers';

const tab = (page: import('@playwright/test').Page, name: RegExp) => page.getByRole('tab', { name });

test.describe('Android app — Back from a job returns to the same Jobs tab (#809888)', () => {
  test('Jobs → Pending → open a job → Back → Jobs on Pending (?tab=pending); reload keeps the tab #809888 @android @prod-safe', async ({ asUser }) => {
    const page = await asUser(ROLE);
    await setEnglish(page);
    await page.goto(pp('/jobs?tab=pending'));
    await expect(tab(page, /^Pending/)).toHaveAttribute('aria-selected', 'true', { timeout: 30_000 });

    await page.getByText(/^JOB-\d{4}$/).filter({ visible: true }).first().click();
    await page.waitForURL(/\/JobDetail\?id=/, { timeout: 30_000 });

    await page.goBack();
    await expect(page, 'вкладка в адресе (комментарий программиста: ?tab=pending)').toHaveURL(/\/jobs\?.*tab=pending/i);
    await expect(tab(page, /^Pending/), 'после Back выбрана Pending, не Submitted').toHaveAttribute('aria-selected', 'true');
    await expect(tab(page, /^Submitted/)).toHaveAttribute('aria-selected', 'false');

    await page.reload();
    await expect(tab(page, /^Pending/), 'обновление сохраняет вкладку').toHaveAttribute('aria-selected', 'true', { timeout: 30_000 });
  });

  test('Direct /jobs without ?tab opens the default tab without errors #809888 @android @prod-safe', async ({ asUser }) => {
    const page = await asUser(ROLE);
    const errors: string[] = [];
    page.on('pageerror', (e) => errors.push(e.message));
    await setEnglish(page);
    await page.goto(pp('/jobs'));
    await expect(page.getByRole('tab', { selected: true }).first()).toBeVisible({ timeout: 30_000 });
    expect(errors, 'ошибок страницы нет').toEqual([]);
  });

  test.describe('real device', () => {
    test.skip(true, 'нужен Android через CDP: системная «Назад» (adb KEYCODE_BACK) со страницы работы в APK Techory Dev');
    test('System Back from JobDetail returns to Jobs → Pending (3/3) #809888 @android', async () => {
      // Techory Dev → Jobs → Pending → JOB-0002 → системная «Назад» → вкладка Pending (факты 17.11: 3/3).
    });
  });
});
